# == Author synonyms: alternate names --> canonical name ===============
AUTHOR_SYNONYMS = {
    "skittykat": "skitty",
}


def resolve_author(username):
    """Map alternate usernames to their canonical form."""
    return AUTHOR_SYNONYMS.get(username, username)


def random_playcount_replacement():
    """Pick a random unicode replacement for a missing playcount."""
    return random.choice(PLAYCOUNT_REPLACEMENTS)
